    fn match_linear_memory_copy_loop(
        code: &[u8],
        mut ip: usize,
    ) -> Option<(u16, Option<u16>, u16, Option<u16>, u16, u16, u16)> {
        fn decode_base_offset_i(
            code: &[u8],
            ip: &mut usize,
            i_slot: u16,
        ) -> Option<(u16, Option<u16>)> {
            if VM::decode_op_at(code, ip)? != Op::LOCAL_GET {
                return None;
            }
            let base_slot = VM::decode_u16_at(code, ip)?;
            if VM::decode_op_at(code, ip)? != Op::LOCAL_GET {
                return None;
            }
            let first_addr_slot = VM::decode_u16_at(code, ip)?;
            if first_addr_slot == i_slot {
                if VM::decode_op_at(code, ip)? != Op::I32_ADD {
                    return None;
                }
                let after_base_i = *ip;
                match VM::decode_op_at(code, ip)? {
                    Op::LOCAL_GET => {
                        let offset_slot = VM::decode_u16_at(code, ip)?;
                        if VM::decode_op_at(code, ip)? != Op::I32_ADD {
                            *ip = after_base_i;
                            return Some((base_slot, None));
                        }
                        return Some((base_slot, Some(offset_slot)));
                    }
                    _ => {
                        *ip = after_base_i;
                        return Some((base_slot, None));
                    }
                }
            }
            if VM::decode_op_at(code, ip)? != Op::I32_ADD {
                return None;
            }
            if VM::decode_op_at(code, ip)? != Op::LOCAL_GET {
                return None;
            }
            if VM::decode_u16_at(code, ip)? != i_slot {
                return None;
            }
            if VM::decode_op_at(code, ip)? != Op::I32_ADD {
                return None;
            }
            Some((base_slot, Some(first_addr_slot)))
        }

        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        let i_slot = Self::decode_u16_at(code, &mut ip)?;
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        let len_slot = Self::decode_u16_at(code, &mut ip)?;
        if Self::decode_op_at(code, &mut ip)? != Op::I32_GE_U {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::BR_IF {
            return None;
        }
        if Self::decode_leb_u32_at(code, &mut ip)? != 1 {
            return None;
        }
        let (src_slot, src_offset_slot) = decode_base_offset_i(code, &mut ip, i_slot)?;
        if Self::decode_op_at(code, &mut ip)? != Op::I32_LOAD8_U {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_SET {
            return None;
        }
        let byte_slot = Self::decode_u16_at(code, &mut ip)?;
        let (dst_slot, dst_offset_slot) = decode_base_offset_i(code, &mut ip, i_slot)?;
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        if Self::decode_u16_at(code, &mut ip)? != byte_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_STORE8 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_GET {
            return None;
        }
        if Self::decode_u16_at(code, &mut ip)? != i_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_CONST {
            return None;
        }
        if Self::decode_leb_i32_at(code, &mut ip)? != 1 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::I32_ADD {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::LOCAL_SET {
            return None;
        }
        if Self::decode_u16_at(code, &mut ip)? != i_slot {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::BR {
            return None;
        }
        if Self::decode_leb_u32_at(code, &mut ip)? != 0 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::END {
            return None;
        }
        Some((
            src_slot,
            src_offset_slot,
            dst_slot,
            dst_offset_slot,
            len_slot,
            i_slot,
            byte_slot,
        ))
    }

