    fn match_br_table_noop_countdown_loop(code: &[u8], mut ip: usize) -> Option<u16> {
        if Self::decode_op_at(code, &mut ip)? != Op::BLOCK {
            return None;
        }
        if *code.get(ip)? != 0 || *code.get(ip + 1)? != 0 {
            return None;
        }
        ip += 2;
        if Self::decode_op_at(code, &mut ip)? != Op::I32_CONST {
            return None;
        }
        let _selector = Self::decode_leb_i32_at(code, &mut ip)?;
        if Self::decode_op_at(code, &mut ip)? != Op::BR_TABLE {
            return None;
        }
        let target_count = Self::decode_leb_u32_at(code, &mut ip)? as usize;
        for _ in 0..target_count {
            if Self::decode_leb_u32_at(code, &mut ip)? != 0 {
                return None;
            }
        }
        if Self::decode_leb_u32_at(code, &mut ip)? != 0 {
            return None;
        }
        if Self::decode_op_at(code, &mut ip)? != Op::END {
            return None;
        }
        Self::match_i32_countdown_loop(code, ip)
    }

