    fn try_local_i64_compare_const_loop(
        &mut self,
        src_slot: u16,
        dst_slot: u16,
        rhs: i64,
        op: Op,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let src = self.stack_i64_at(base + src_slot as usize)?;
        let result = match op {
            Op::I64_EQ => src == rhs,
            Op::I64_NE => src != rhs,
            Op::I64_LT_S => src < rhs,
            Op::I64_LT_U => (src as u64) < (rhs as u64),
            Op::I64_GT_S => src > rhs,
            Op::I64_GT_U => (src as u64) > (rhs as u64),
            Op::I64_LE_S => src <= rhs,
            Op::I64_LE_U => (src as u64) <= (rhs as u64),
            Op::I64_GE_S => src >= rhs,
            Op::I64_GE_U => (src as u64) >= (rhs as u64),
            _ => return Ok(false),
        };
        self.stack[base + dst_slot as usize] = Value::I32(result as i32);
        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_local_i64_cmp_const_loop =
                counters.super_local_i64_cmp_const_loop.saturating_add(1);
            match op {
                Op::I64_EQ => counters.i64_eq = counters.i64_eq.saturating_add(n),
                Op::I64_NE => counters.i64_ne = counters.i64_ne.saturating_add(n),
                Op::I64_LT_S => counters.i64_lt_s = counters.i64_lt_s.saturating_add(n),
                Op::I64_LT_U => counters.i64_lt_u = counters.i64_lt_u.saturating_add(n),
                Op::I64_GT_S => counters.i64_gt_s = counters.i64_gt_s.saturating_add(n),
                Op::I64_GT_U => counters.i64_gt_u = counters.i64_gt_u.saturating_add(n),
                Op::I64_LE_S => counters.i64_le_s = counters.i64_le_s.saturating_add(n),
                Op::I64_LE_U => counters.i64_le_u = counters.i64_le_u.saturating_add(n),
                Op::I64_GE_S => counters.i64_ge_s = counters.i64_ge_s.saturating_add(n),
                Op::I64_GE_U => counters.i64_ge_u = counters.i64_ge_u.saturating_add(n),
                _ => {}
            }
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(2));
            counters.local_set = counters.local_set.saturating_add(n);
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

