    fn try_call_i32_add_loop(
        &mut self,
        caller_chunk_index: usize,
        import_idx: u16,
        acc_slot: u16,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let target = match self.resolve_chunk_import(caller_chunk_index, import_idx as usize)? {
            Some(ImportTarget::ChunkFn { chunk_index, arity }) if arity == 1 => chunk_index,
            _ => return Ok(false),
        };
        if !self.func_switches.is_empty() && self.func_switches.contains_key(&target) {
            return Ok(false);
        }
        let Some(add) = self.match_i32_add_const_function(target) else {
            return Ok(false);
        };

        let acc = self.stack_i32_at(base + acc_slot as usize)?;
        self.stack[base + acc_slot as usize] =
            Value::I32(acc.wrapping_add(add.wrapping_mul(count)));
        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_call_i32_add_loop = counters.super_call_i32_add_loop.saturating_add(1);
            counters.call = counters.call.saturating_add(n);
            counters.function_call = counters.function_call.saturating_add(n);
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(3));
            counters.local_set = counters.local_set.saturating_add(n);
            counters.i32_add = counters.i32_add.saturating_add(n.saturating_mul(2));
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

