    fn try_global_set_local_loop(
        &mut self,
        global_idx: u32,
        value_slot: u16,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }

        let idx = global_idx as usize;
        let val = self.stack[base + value_slot as usize].clone();
        if idx >= self.globals.len() {
            self.globals.resize(idx + 1, Value::Null);
        }
        if idx >= self.globals_assigned.len() {
            self.globals_assigned.resize(idx + 1, false);
        }
        unsafe {
            *self.globals.get_unchecked_mut(idx) = val;
            *self.globals_assigned.get_unchecked_mut(idx) = true;
        }

        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_global_set_local_loop =
                counters.super_global_set_local_loop.saturating_add(1);
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(2));
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

