    fn try_array_get_drop_loop(
        &mut self,
        arr_slot: u16,
        index: i32,
        counter_slot: u16,
        end_ip: usize,
    ) -> Result<bool, VMError> {
        let frame_index = self.frames.len() - 1;
        let base = self.frames[frame_index].base;
        let count = self.stack_i32_at(base + counter_slot as usize)?;
        if count <= 0 {
            return Ok(false);
        }
        if index < 0 {
            return Ok(false);
        }

        let obj = match self.stack.get(base + arr_slot as usize) {
            Some(Value::Object(o)) => o,
            _ => return Ok(false),
        };
        let idx = index as usize;
        let in_bounds_dense = {
            if let Some(counters) = self.perf_counters.as_mut() {
                counters.record_object_lock();
            }
            let ob = obj.lock().unwrap();
            let is_gc = ob.type_id > 0
                && self
                    .type_registry
                    .get(ob.type_id)
                    .is_some_and(|td| td.is_array());
            let ObjectKind::Array(a) = &ob.kind else {
                return Ok(false);
            };
            if is_gc && idx >= a.len() {
                return Err(VMError::new("trap: out of bounds array access (array.get)"));
            }
            idx < a.len()
        };
        if !in_bounds_dense {
            return Ok(false);
        }

        self.stack[base + counter_slot as usize] = Value::I32(0);
        self.label_stack.pop();
        self.frames[frame_index].ip = end_ip.saturating_add(4);
        if let Some(counters) = self.perf_counters.as_mut() {
            let n = count as u64;
            counters.super_array_get_drop_loop =
                counters.super_array_get_drop_loop.saturating_add(1);
            counters.array_get = counters.array_get.saturating_add(n);
            counters.array_get_dense = counters.array_get_dense.saturating_add(n);
            counters.local_get = counters.local_get.saturating_add(n.saturating_mul(2));
            counters.br_if = counters.br_if.saturating_add(n);
            counters.br_if_taken = counters.br_if_taken.saturating_add(n.saturating_sub(1));
            counters.br_if_not_taken = counters.br_if_not_taken.saturating_add(1);
        }
        Ok(true)
    }

